import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        x, y, v = map(int, sys.stdin.readline().split())
        adj[x].append((y, v))
        adj[y].append((x, v))

    leaves = []
    parent = [0]*(n+1)
    depth = [0]*(n+1)
    dist = [0]*(n+1)
    q = deque()
    q.append(1)
    parent[1] = 0
    while q:
        u = q.popleft()
        for v, w in adj[u]:
            if parent[v] == 0 and v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                dist[v] = dist[u] + w
                q.append(v)
    for u in range(1, n+1):
        if len(adj[u]) == 1 and u != 1:
            leaves.append(u)

    max_depth = max(depth[u] for u in leaves)
    leaves_dist = [0]*(n+1)
    for u in leaves:
        leaves_dist[u] = dist[u]

    for u in range(1, n+1):
        if u not in leaves:
            max_dist = 0
            for v, w in adj[u]:
                if v != parent[u]:
                    max_dist = max(max_dist, leaves_dist[v] + w)
            leaves_dist[u] = max_dist

    q = int(sys.stdin.readline())
    ls = list(map(int, sys.stdin.readline().split()))

    for l in ls:
        res = 0
        for u in range(1, n+1):
            max_d = 0
            min_d = float('inf')
            stack = [(u, 0)]
            visited = [False]*(n+1)
            visited[u] = True
            while stack:
                node, d = stack.pop()
                max_d = max(max_d, leaves_dist[node] - d)
                min_d = min(min_d, leaves_dist[node] - d)
                for v, w in adj[node]:
                    if not visited[v] and v != parent[node]:
                        visited[v] = True
                        stack.append((v, d + w))
            if max_d - min_d <= l:
                res = max(res, 1)
            else:
                continue
            stack = [(u, 0)]
            visited = [False]*(n+1)
            visited[u] = True
            cnt = 0
            while stack:
                node, d = stack.pop()
                cnt += 1
                for v, w in adj[node]:
                    if not visited[v] and v != parent[node]:
                        visited[v] = True
                        stack.append((v, d + w))
            res = max(res, cnt)
        print(res)

if __name__ == '__main__':
    main()
